var cp = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/CommandScrollContainer/CommandPanel")
if cp == null:
	return "no command panel"
var kids = cp.get_children()
var is_rule = []
for c in kids:
	is_rule.append(c is ColorRect and (c.has_meta("command_gold_separator") or int(c.custom_minimum_size.y) == 2))
var orphans = []
for i in range(kids.size()):
	if not is_rule[i]:
		continue
	var next_i = -1
	for j in range(i + 1, kids.size()):
		if kids[j] is Control and not kids[j].visible:
			continue
		next_i = j
		break
	if next_i == -1 or is_rule[next_i]:
		orphans.append(i)
if orphans.size() > 0:
	return "orphan gold rules at child indexes %s of %d" % [str(orphans), kids.size()]
return "clean"

var b = tree.root.get_node_or_null("/root/SecondaryMissionReviewDialog/OuterScroll/MainContainer/ButtonRow/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false

